/**
 * 听见（listen）— Cloudflare Worker
 *
 * 给听障人士的实时语音转写：手机麦克风 → 16k PCM → WebSocket 透明代理 → 火山引擎豆包流式语音识别大模型。
 *
 * GET  /                      → 单文件前端页面（内容由 src/deploy.js 注入到下方标记）
 * GET  /favicon.svg           → 站点图标（内联 SVG）
 * GET  /manifest.webmanifest  → PWA manifest
 * GET  /icon-192.png /icon-512.png → PWA 图标（src/icons.js，scripts/gen-icons.mjs 生成）
 * POST /api/auth              → 密码换会话票据（12h，HMAC 签名；改密码 = 吊销全部存量票据）
 * GET  /ws?ticket=<ticket>    → WebSocket 代理到火山引擎（验票 + 带鉴权 Header 拨号 + 双向字节透传）
 *                                v1.1 起也接受 room token（访客 ASR，PLAN.md §11）
 * POST /api/room              → 建远程字聊房间（凭 app 票据；DO 初始化，返回 code + host room token）
 * POST /api/join              → 访客用一次性 code 换 guest room token（10 分钟窗口，首位即烧毁）
 * GET  /j/:code               → 访客落地页（同一份前端，按路径进访客模式）
 * GET  /room/:code?token=     → 字聊房间 WebSocket → ChatRoom Durable Object（纯 JSON 文本中继）
 *
 * 环境变量（wrangler secret put 或 Dashboard 配置，见 wrangler.toml 注释）：
 *   ACCESS_PASSWORD    进入口令（改密码 = 吊销全部已发 ticket 与房间 token）
 *   VOLC_APP_ID        火山引擎 APP ID
 *   VOLC_ACCESS_TOKEN  火山引擎 Access Token
 *   JOIN_WINDOW_SECONDS / ROOM_TTL_MINUTES / ROOM_TTL_SECONDS  房间生命周期（可选，有默认值）
 */

// 图标 base64 由 scripts/gen-icons.mjs 生成到 src/icons.js（改设计重跑生成器，勿手改）
import { ICON_192_PNG, ICON_512_PNG } from './src/icons.js';

// ================= JSON 响应与工具 =================

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'Content-Type': 'application/json;charset=UTF-8',
      'Cache-Control': 'no-store'
    }
  });
}

// ================= 票据鉴权（PLAN.md §3.1；v1.1 增 room token，§11.2） =================
// app 票据   = b64url(JSON{jti,exp}) + "." + b64url(HMAC-SHA256(payload, SHA256(ACCESS_PASSWORD+"listen-ticket-v1")))
// room token = b64url(JSON{scope:'room',room,role,jti,exp}) + "." + b64url(HMAC-SHA256(payload, SHA256(ACCESS_PASSWORD+"listen-room-v1")))
// 只签名不加密；改密码 = 换 HMAC key = 全部存量票据/房间 token 失效，无需撤销列表。

const TICKET_TTL_MS = 12 * 3600 * 1000; // 12h：长对话场景不宜太短
const TICKET_KEY_SALT = 'listen-ticket-v1';
const ROOM_KEY_SALT = 'listen-room-v1'; // 与 app 票据不同域 → 改密码连坐吊销房间
const ROOM_CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // 32 字符，去 0/O/1/I（§11.2）
const AUTH_MAX_BODY_BYTES = 4096; // /api/auth 请求体上限
const AUTH_FAIL_LIMIT = 10; // 连续错密码次数上限
const AUTH_LOCK_MS = 15 * 60 * 1000; // 锁定时长

// per-IP 防爆破（模块级 Map，per-isolate 尽力而为，PLAN.md §6 取舍）
const authFails = new Map(); // ip → { fails, lockedUntil }

const te = new TextEncoder();

// 常量时间比较（等长字节；不等长直接 false——长度本身在这里不是秘密）
function timingSafeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

// 密码比对：两边先 SHA-256 再常量时间比较摘要（避免长度/前缀信息泄露）
async function passwordMatches(provided, expected) {
  if (typeof provided !== 'string' || !expected) return false;
  const [a, b] = await Promise.all([
    crypto.subtle.digest('SHA-256', te.encode(provided)),
    crypto.subtle.digest('SHA-256', te.encode(expected))
  ]);
  return timingSafeEqual(new Uint8Array(a), new Uint8Array(b));
}

function b64urlFromBytes(bytes) {
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function b64urlToBytes(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  const bin = atob(s); // 非法字符会 throw，由调用方兜
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function getTicketKey(password, salt = TICKET_KEY_SALT) {
  const material = await crypto.subtle.digest(
    'SHA-256',
    te.encode(password + salt)
  );
  return crypto.subtle.importKey(
    'raw', material, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
  );
}

async function issueTicket(password) {
  const jti = crypto.randomUUID();
  const exp = Date.now() + TICKET_TTL_MS;
  const payloadB64 = b64urlFromBytes(te.encode(JSON.stringify({ jti, exp })));
  const key = await getTicketKey(password);
  const sig = await crypto.subtle.sign('HMAC', key, te.encode(payloadB64));
  return { ticket: payloadB64 + '.' + b64urlFromBytes(new Uint8Array(sig)), exp, jti };
}

// 校验凭证（双格式）：分段 → 解 payload 定 scope（选 HMAC 域）→ 验签（常量时间）→ 字段与 exp 检查。
// app 票据要求 {jti,exp}；room token 额外要求 room 格式与 role 合法。任何一步失败返回 null（/ws 复用）。
async function verifyTicket(ticket, password) {
  if (typeof ticket !== 'string' || !password) return null;
  const dot = ticket.indexOf('.');
  if (dot <= 0 || ticket.indexOf('.', dot + 1) !== -1) return null; // 必须恰好 payload.sig 两段
  const payloadB64 = ticket.slice(0, dot);
  const sigB64 = ticket.slice(dot + 1);
  let sig;
  try {
    sig = b64urlToBytes(sigB64);
  } catch {
    return null;
  }
  if (sig.length !== 32) return null; // HMAC-SHA256 摘要固定 32 字节
  let payload;
  try {
    payload = JSON.parse(new TextDecoder().decode(b64urlToBytes(payloadB64)));
  } catch {
    return null;
  }
  if (!payload || typeof payload !== 'object') return null;
  const isRoom = payload.scope === 'room';
  const key = await getTicketKey(password, isRoom ? ROOM_KEY_SALT : TICKET_KEY_SALT);
  const expect = new Uint8Array(await crypto.subtle.sign('HMAC', key, te.encode(payloadB64)));
  if (!timingSafeEqual(sig, expect)) return null;
  if (typeof payload.jti !== 'string' || !payload.jti) return null;
  if (typeof payload.exp !== 'number' || payload.exp < Date.now()) return null;
  if (isRoom) {
    if (typeof payload.room !== 'string' || !/^[A-Z2-9]{6}$/.test(payload.room)) return null;
    if (payload.role !== 'host' && payload.role !== 'guest') return null;
  }
  return payload;
}

// room token 签发（host 建房时 / guest 在 /api/join 换取；exp = 房间 hardEnd，§11.2）
async function issueRoomToken(password, room, role, exp) {
  const payload = { scope: 'room', room, role, jti: crypto.randomUUID(), exp };
  const payloadB64 = b64urlFromBytes(te.encode(JSON.stringify(payload)));
  const key = await getTicketKey(password, ROOM_KEY_SALT);
  const sig = await crypto.subtle.sign('HMAC', key, te.encode(payloadB64));
  return { token: payloadB64 + '.' + b64urlFromBytes(new Uint8Array(sig)) };
}

function genRoomCode() {
  const bytes = crypto.getRandomValues(new Uint8Array(6));
  let code = '';
  for (let i = 0; i < bytes.length; i++) code += ROOM_CODE_ALPHABET[bytes[i] % ROOM_CODE_ALPHABET.length];
  return code;
}

function clientIp(request) {
  return (
    request.headers.get('CF-Connecting-IP') ||
    (request.headers.get('x-forwarded-for') || '').split(',')[0].trim() ||
    'unknown'
  );
}

async function handleAuth(request, env) {
  const password = env.ACCESS_PASSWORD;
  if (!password) {
    return jsonResponse({ error: '服务未配置，请联系管理员。' }, 500);
  }

  const ip = clientIp(request);
  const now = Date.now();
  const rec = authFails.get(ip);
  if (rec && rec.lockedUntil > now) {
    return jsonResponse({ error: '错误次数太多，请 15 分钟后再试。' }, 429);
  }

  const lenHeader = Number(request.headers.get('content-length') || 0);
  if (lenHeader > AUTH_MAX_BODY_BYTES) {
    return jsonResponse({ error: '请求体过大。' }, 413);
  }
  let body;
  try {
    body = JSON.parse(await request.text());
  } catch {
    return jsonResponse({ error: '请求格式不对。' }, 400);
  }
  if (body && typeof body === 'object' && JSON.stringify(body).length > AUTH_MAX_BODY_BYTES) {
    return jsonResponse({ error: '请求体过大。' }, 413);
  }

  if (await passwordMatches(body && body.password, password)) {
    authFails.delete(ip);
    const { ticket, exp } = await issueTicket(password);
    return jsonResponse({ ticket, expiresAt: exp });
  }

  const fails = (rec ? rec.fails : 0) + 1;
  if (fails >= AUTH_FAIL_LIMIT) {
    authFails.set(ip, { fails, lockedUntil: now + AUTH_LOCK_MS });
  } else {
    authFails.set(ip, { fails, lockedUntil: 0 });
  }
  return jsonResponse({ error: '密码不对，请重试。' }, 401);
}

// ================= WebSocket 透明代理（PLAN.md §3.2，核心链路） =================
// 职责严格三件事：验票 → 带鉴权 Header 向上游发起升级（浏览器做不到、fetch 能做的关键点）
// → 双向原样字节转发。不解析音频、不组装协议帧（协议帧全部由客户端构造）。

const VOLC_ENDPOINT_DEFAULT = 'https://openspeech.bytedance.com/api/v3/sauc/bigmodel_async';
const VOLC_RESOURCE_ID_DEFAULT = 'volc.bigasr.sauc.duration';
const MAX_SESSION_MINUTES_DEFAULT = 120; // 计费护栏：单条连接时长上限
const MAX_TICKET_CONNS = 2; // per-ticket 并发上限

const ticketConns = new Map(); // jti → 活跃连接数（模块级，尽力而为）

async function handleWs(request, env, url) {
  const password = env.ACCESS_PASSWORD;
  if (!password || !env.VOLC_APP_ID || !env.VOLC_ACCESS_TOKEN) {
    return jsonResponse({ error: '服务未配置，请联系管理员。' }, 500);
  }

  // 1. 验票（失败不升级，客户端据此静默重新 /api/auth）
  const payload = await verifyTicket(url.searchParams.get('ticket'), password);
  if (!payload) {
    return jsonResponse({ error: '票据无效或已过期，请重新进入。' }, 401);
  }
  const jti = payload.jti;

  // 2. per-ticket 并发上限：完成升级后立即 close(1013)，客户端按关闭码统一处理
  if ((ticketConns.get(jti) || 0) >= MAX_TICKET_CONNS) {
    const [overClient, overServer] = Object.values(new WebSocketPair());
    overServer.accept();
    overServer.close(1013, '同一票据连接数超限，请稍后再试');
    return new Response(null, { status: 101, webSocket: overClient });
  }

  // 并发槽在拨号前预占（否则多条连接并发拨号时会同时通过上限检查），失败路径回退
  ticketConns.set(jti, (ticketConns.get(jti) || 0) + 1);
  const releaseSlot = () => {
    const n = (ticketConns.get(jti) || 1) - 1;
    if (n > 0) ticketConns.set(jti, n);
    else ticketConns.delete(jti);
  };

  // 3. 出站拨号：带火山鉴权 Header 的升级请求
  let upstreamRes;
  try {
    upstreamRes = await fetch(env.VOLC_ENDPOINT || VOLC_ENDPOINT_DEFAULT, {
      headers: {
        Upgrade: 'websocket',
        'X-Api-App-Key': env.VOLC_APP_ID,
        'X-Api-Access-Key': env.VOLC_ACCESS_TOKEN,
        'X-Api-Resource-Id': env.VOLC_RESOURCE_ID || VOLC_RESOURCE_ID_DEFAULT,
        'X-Api-Connect-Id': jti
      }
    });
  } catch (err) {
    releaseSlot();
    return jsonResponse({ error: '连不上语音服务，请检查网络。' }, 502);
  }
  if (!upstreamRes.webSocket) {
    // 只回传上游 status 便于排查，绝不回传鉴权 Header/凭证
    releaseSlot();
    return jsonResponse(
      { error: '语音服务连接失败（上游 ' + upstreamRes.status + '）。' },
      502
    );
  }

  // 4. 两侧接线，双向原样转发
  const upstream = upstreamRes.webSocket;
  upstream.accept();
  const [client, server] = Object.values(new WebSocketPair());
  server.accept();

  const maxSessionMs =
    (parseInt(env.MAX_SESSION_MINUTES, 10) || MAX_SESSION_MINUTES_DEFAULT) * 60 * 1000;
  let firstMsgAt = 0; // 会话时长从首条消息起算

  let closed = false;
  const dec = () => {
    // 计数只减一次
    if (closed) return;
    closed = true;
    const n = (ticketConns.get(jti) || 1) - 1;
    if (n > 0) ticketConns.set(jti, n);
    else ticketConns.delete(jti);
  };

  server.addEventListener('message', e => {
    if (!firstMsgAt) {
      firstMsgAt = Date.now();
    } else if (Date.now() - firstMsgAt > maxSessionMs) {
      try { upstream.close(1008, '会话超时'); } catch {}
      try { server.close(1008, '会话超时'); } catch {}
      dec();
      return;
    }
    upstream.send(e.data); // 二进制直传，禁止 String 化
  });
  upstream.addEventListener('message', e => {
    server.send(e.data);
  });

  // 双向 close/error 传播（code/reason 透传，含服务端正常结束的 1000）
  server.addEventListener('close', e => {
    try { upstream.close(e.code, e.reason); } catch {}
    dec();
  });
  upstream.addEventListener('close', e => {
    try { server.close(e.code, e.reason); } catch {}
    dec();
  });
  server.addEventListener('error', () => {
    try { upstream.close(1011, '连接异常'); } catch {}
    dec();
  });
  upstream.addEventListener('error', () => {
    try { server.close(1011, '连接异常'); } catch {}
    dec();
  });

  return new Response(null, { status: 101, webSocket: client });
}

// ================= 远程字聊：房间 API + ChatRoom DO（PLAN.md §11） =================

const JOIN_WINDOW_SECONDS_DEFAULT = 600; // 邀请码加入窗口
const ROOM_TTL_MINUTES_DEFAULT = 120;    // 房间硬顶（计费护栏）
const ROOM_LINE_BACKLOG = 200;           // DO 保存的定稿行数上限（重连补发）

// /api/join per-IP 限流（防 code 爆破，内存尽力而为，§11.2）
const joinHits = new Map(); // ip → { count, windowStart }
const JOIN_RATE_LIMIT = 20;
const JOIN_RATE_WINDOW_MS = 60 * 1000;

function roomLifecycle(env) {
  const now = Date.now();
  const joinWindowMs =
    (parseInt(env.JOIN_WINDOW_SECONDS, 10) || JOIN_WINDOW_SECONDS_DEFAULT) * 1000;
  const ttlMs = env.ROOM_TTL_SECONDS != null
    ? parseFloat(env.ROOM_TTL_SECONDS) * 1000 // 秒级覆盖（测试用）
    : (parseFloat(env.ROOM_TTL_MINUTES) || ROOM_TTL_MINUTES_DEFAULT) * 60 * 1000;
  return { joinDeadline: now + joinWindowMs, hardEnd: now + ttlMs };
}

async function readJsonBody(request) {
  try {
    return [null, JSON.parse(await request.text())];
  } catch {
    return [{ error: '请求格式不对。' }, null];
  }
}

function roomStub(env, code) {
  return env.ROOM.get(env.ROOM.idFromName(code));
}

// POST /api/room：凭 app 票据建房（room token 无此权限）
async function handleCreateRoom(request, env) {
  const password = env.ACCESS_PASSWORD;
  if (!password || !env.ROOM) {
    return jsonResponse({ error: '服务未配置，请联系管理员。' }, 500);
  }
  const [bad, body] = await readJsonBody(request);
  if (bad) return jsonResponse(bad, 400);
  const payload = await verifyTicket(body && body.ticket, password);
  if (!payload || payload.scope === 'room') {
    return jsonResponse({ error: '票据无效或已过期，请重新进入。' }, 401);
  }
  const code = genRoomCode();
  const { joinDeadline, hardEnd } = roomLifecycle(env);
  let initRes;
  try {
    initRes = await roomStub(env, code).fetch('https://room/init', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ joinDeadline, hardEnd })
    });
  } catch {
    return jsonResponse({ error: '房间创建失败，请重试。' }, 502);
  }
  if (!initRes.ok) return jsonResponse({ error: '房间创建失败，请重试。' }, 500);
  const { token } = await issueRoomToken(password, code, 'host', hardEnd);
  return jsonResponse({ code, token, joinUrl: '/j/' + code, joinDeadline, hardEnd });
}

// POST /api/join：访客用一次性 code 换 guest room token（首位即烧毁，§11.2）
async function handleJoin(request, env) {
  const password = env.ACCESS_PASSWORD;
  if (!password || !env.ROOM) {
    return jsonResponse({ error: '服务未配置，请联系管理员。' }, 500);
  }
  const ip = clientIp(request);
  const now = Date.now();
  const rec = joinHits.get(ip) || { count: 0, windowStart: now };
  if (now - rec.windowStart > JOIN_RATE_WINDOW_MS) {
    rec.count = 0;
    rec.windowStart = now;
  }
  rec.count++;
  joinHits.set(ip, rec);
  if (rec.count > JOIN_RATE_LIMIT) {
    return jsonResponse({ error: '尝试太频繁，请一分钟后再试。' }, 429);
  }

  const [bad, body] = await readJsonBody(request);
  if (bad) return jsonResponse(bad, 400);
  const code = String((body && body.code) || '').trim().toUpperCase();
  if (!/^[A-Z2-9]{6}$/.test(code)) {
    return jsonResponse({ error: '邀请码不存在或已过期，请对方重新发起。' }, 404);
  }
  let res;
  try {
    res = await roomStub(env, code).fetch('https://room/claim', { method: 'POST' });
  } catch {
    return jsonResponse({ error: '加入失败，请稍后再试。' }, 502);
  }
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    const msg = err.error === 'used'
      ? '邀请码已被使用，请对方重新发起。'
      : '邀请码不存在或已过期，请对方重新发起。';
    return jsonResponse({ error: msg }, 404);
  }
  const data = await res.json();
  const { token } = await issueRoomToken(password, code, 'guest', data.hardEnd);
  return jsonResponse({ token, role: 'guest', hardEnd: data.hardEnd });
}

// GET /room/:code?token=：验 room token（签名/exp/房间一致）后转交 DO（role 已验签，经查询串传递）
async function handleRoomWs(request, env, url) {
  const password = env.ACCESS_PASSWORD;
  if (!password || !env.ROOM) {
    return jsonResponse({ error: '服务未配置，请联系管理员。' }, 500);
  }
  const code = url.pathname.slice('/room/'.length).trim().toUpperCase();
  const payload = await verifyTicket(url.searchParams.get('token'), password);
  if (!payload || payload.scope !== 'room' || payload.room !== code) {
    return jsonResponse({ error: '凭证无效或已过期。' }, 401);
  }
  // 复制原升级请求（保留 Upgrade 头），路径换成 DO 内部 /ws
  return roomStub(env, code).fetch(new Request('https://room/ws?role=' + payload.role, request));
}

// ChatRoom Durable Object：每邀请码一个实例，纯 JSON 文本中继（§11.3）。
// meta/定稿行存 state.storage（SQLite），DO 被逐出后重启可恢复；成员表只能在内存（WS 不可序列化）。
// alarm() 在 hardEnd 兜底关房并清存储（计费护栏）。
export class ChatRoom {
  constructor(state, env) {
    this.state = state;
    this.env = env;
    this.members = new Map(); // role → ws（host/guest 各一 slot，同 role 重连顶替）
    this.meta = null;
    this.lines = [];
    this.seq = 0;
    this.loaded = false;
  }

  async load() {
    if (this.loaded) return;
    this.loaded = true;
    this.meta = (await this.state.storage.get('meta')) || null;
    this.lines = (await this.state.storage.get('lines')) || [];
    this.seq = (await this.state.storage.get('seq')) || 0;
  }

  other(role) {
    return role === 'host' ? 'guest' : 'host';
  }

  sendTo(ws, obj) {
    try { ws.send(JSON.stringify(obj)); } catch {}
  }

  async fetch(request) {
    const url = new URL(request.url);
    await this.load();

    if (url.pathname === '/init' && request.method === 'POST') {
      if (!this.meta) {
        let body = {};
        try { body = JSON.parse(await request.text()); } catch {}
        this.meta = {
          createdAt: Date.now(),
          joinDeadline: Number(body.joinDeadline) || Date.now(),
          hardEnd: Number(body.hardEnd) || Date.now() + 3600 * 1000,
          consumed: false,
          closed: false
        };
        await this.state.storage.put('meta', this.meta);
        await this.state.storage.setAlarm(this.meta.hardEnd);
      }
      return jsonResponse({ ok: true });
    }

    if (url.pathname === '/claim' && request.method === 'POST') {
      if (!this.meta || this.meta.closed) return jsonResponse({ error: 'gone' }, 404);
      if (this.meta.consumed) return jsonResponse({ error: 'used' }, 404);
      if (Date.now() > this.meta.joinDeadline) return jsonResponse({ error: 'expired' }, 404);
      this.meta.consumed = true; // 一次性：签发 guest token 即烧毁
      await this.state.storage.put('meta', this.meta);
      return jsonResponse({ ok: true, hardEnd: this.meta.hardEnd });
    }

    if (url.pathname === '/ws' && request.method === 'GET') {
      const role = url.searchParams.get('role');
      if (role !== 'host' && role !== 'guest') return jsonResponse({ error: '角色无效。' }, 400);
      if (!this.meta || this.meta.closed || Date.now() > this.meta.hardEnd) {
        return jsonResponse({ error: '房间已关闭或已到期。' }, 404);
      }
      const [client, server] = Object.values(new WebSocketPair());
      this.attach(server, role);
      return new Response(null, { status: 101, webSocket: client });
    }

    return jsonResponse({ error: '页面不存在。' }, 404);
  }

  attach(ws, role) {
    const old = this.members.get(role);
    if (old) {
      try { old.close(4000, 'replaced'); } catch {}
    }
    this.members.set(role, ws);
    ws.accept();
    ws.send(JSON.stringify({
      t: 'welcome',
      role,
      peerOnline: this.members.has(this.other(role)),
      backlog: this.lines
    }));
    const peer = this.members.get(this.other(role));
    if (peer) this.sendTo(peer, { t: 'presence', online: true });

    ws.addEventListener('message', e => {
      let msg;
      try { msg = JSON.parse(e.data); } catch { return; }
      if (!msg || typeof msg !== 'object') return;
      if (msg.t === 'ping') {
        this.sendTo(ws, { t: 'pong' });
        return;
      }
      if (msg.t === 'bye') {
        try { ws.close(1000, 'bye'); } catch {}
        return;
      }
      if (msg.t === 'close') { // host 主动关房（挂断语义，§11.4）：双端 room_closed + 清存储
        if (role !== 'host') return;
        this.closeRoom('host');
        return;
      }
      if (msg.t === 'revise' && typeof msg.text === 'string' && msg.text.length <= 2000 &&
          typeof msg.key === 'string' && msg.key.length <= 64) {
        // 定稿对账（v1.1.2 草稿转正）：drop 的行移除、命中行原位换文本（保序号/位置），未命中则追加；持久化 + 转发对端
        const drops = Array.isArray(msg.drop)
          ? msg.drop.filter(k => typeof k === 'string' && k.length <= 64) : [];
        let idx = -1;
        for (let i = 0; i < this.lines.length; i++) {
          const k = this.lines[i].key;
          if (drops.indexOf(k) >= 0 || k === msg.key) { idx = i; break; }
        }
        if (idx >= 0) {
          const keptSeq = this.lines[idx].seq;
          this.lines.splice(idx, 1, { from: role, kind: 'final', key: msg.key, text: msg.text, seq: keptSeq });
          this.lines = this.lines.filter((l, i) => i === idx || drops.indexOf(l.key) < 0);
        } else {
          this.lines.push({ from: role, kind: 'final', key: msg.key, text: msg.text, seq: ++this.seq });
          this.state.storage.put('seq', this.seq).catch(() => {});
        }
        this.state.storage.put('lines', this.lines).catch(() => {});
        const peerNow = this.members.get(this.other(role));
        if (peerNow) this.sendTo(peerNow, { t: 'revise', key: msg.key, text: msg.text, drop: drops });
        return;
      }
      if (msg.t === 'line' && typeof msg.text === 'string' && msg.text.length <= 2000) {
        const kind = msg.kind === 'final' ? 'final' : 'interim';
        const out = { t: 'line', from: role, kind, key: String(msg.key || ''), text: msg.text };
        if (kind === 'final') {
          out.seq = ++this.seq;
          this.lines.push({ from: role, kind, key: out.key, text: msg.text, seq: out.seq });
          if (this.lines.length > ROOM_LINE_BACKLOG) {
            this.lines.splice(0, this.lines.length - ROOM_LINE_BACKLOG);
          }
          // 尽力持久化（DO 逐出前通常来得及落盘；失败不阻塞转发）
          this.state.storage.put('lines', this.lines).catch(() => {});
          this.state.storage.put('seq', this.seq).catch(() => {});
        }
        const peerNow = this.members.get(this.other(role));
        if (peerNow) this.sendTo(peerNow, out); // interim 对端离线即弃；final 已入 backlog
      }
    });
    const onGone = () => {
      if (this.members.get(role) !== ws) return; // 已被新连接顶替
      this.members.delete(role);
      const peerNow = this.members.get(this.other(role));
      if (peerNow) this.sendTo(peerNow, { t: 'presence', online: false });
    };
    ws.addEventListener('close', onGone);
    ws.addEventListener('error', onGone);
  }

  closeRoom(reason) {
    const note = JSON.stringify({ t: 'room_closed', reason: reason });
    for (const ws of this.members.values()) {
      try { ws.send(note); } catch {}
      try { ws.close(1000, '房间已关闭'); } catch {}
    }
    this.members.clear();
    this.meta = { closed: true }; // 内存哨兵：本实例内拒绝后续 join/ws（持久 meta 已删）
    this.state.storage.deleteAll().catch(() => {});
  }

  async alarm() {
    await this.load();
    if (!this.meta) return;
    this.meta.closed = true;
    for (const ws of this.members.values()) {
      try { ws.send(JSON.stringify({ t: 'room_closed', reason: 'expired' })); } catch {}
      try { ws.close(1001, '房间已到期'); } catch {}
    }
    this.members.clear();
    await this.state.storage.deleteAll();
  }
}

