// ================= 路由 =================

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (request.method === 'GET' && path === '/') {
      return new Response(htmlContent, {
        status: 200,
        headers: {
          'Content-Type': 'text/html;charset=UTF-8',
          'Cache-Control': 'public, max-age=300'
        }
      });
    }

    if (request.method === 'GET' && path === '/favicon.svg') {
      return new Response(FAVICON_SVG, {
        status: 200,
        headers: {
          'Content-Type': 'image/svg+xml',
          'Cache-Control': 'public, max-age=86400'
        }
      });
    }

    if (request.method === 'GET' && path === '/manifest.webmanifest') {
      return new Response(
        JSON.stringify({
          name: '听见 · 实时字幕',
          short_name: '听见',
          description: '给听障人士的实时语音转写字幕',
          start_url: '/',
          display: 'standalone',
          background_color: '#ffffff',
          theme_color: '#0e7a5f',
          icons: [
            { src: '/icon-192.png', sizes: '192x192', type: 'image/png' },
            { src: '/icon-512.png', sizes: '512x512', type: 'image/png' }
          ]
        }),
        {
          status: 200,
          headers: {
            'Content-Type': 'application/manifest+json',
            'Cache-Control': 'public, max-age=86400'
          }
        }
      );
    }

    if (request.method === 'GET' && (path === '/icon-192.png' || path === '/icon-512.png')) {
      const b64 = path === '/icon-192.png' ? ICON_192_PNG : ICON_512_PNG;
      const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
      return new Response(bytes, {
        status: 200,
        headers: {
          'Content-Type': 'image/png',
          'Cache-Control': 'public, max-age=604800'
        }
      });
    }

    if (request.method === 'POST' && path === '/api/auth') {
      return handleAuth(request, env);
    }

    if (request.method === 'POST' && path === '/api/room') {
      return handleCreateRoom(request, env);
    }

    if (request.method === 'POST' && path === '/api/join') {
      return handleJoin(request, env);
    }

    if (request.method === 'GET' && /^\/j\/[A-Za-z0-9]{4,16}\/?$/.test(path)) {
      // 访客落地页：同一份前端（前端按路径 /j/<code> 进访客模式）
      return new Response(htmlContent, {
        status: 200,
        headers: {
          'Content-Type': 'text/html;charset=UTF-8',
          'Cache-Control': 'public, max-age=300'
        }
      });
    }

    if (request.method === 'GET' && path.startsWith('/room/')) {
      return handleRoomWs(request, env, url);
    }

    if (request.method === 'GET' && path === '/ws') {
      return handleWs(request, env, url);
    }

    return jsonResponse({ error: '页面不存在。' }, 404);
  }
};
